package com.cache.distributed

import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.locks.ReentrantReadWriteLock
import java.time.Instant
import java.util.logging.Logger

data class CacheEntry(
    val key: String,
    val value: ByteArray,
    val ttlMs: Long,
    val createdAt: Instant
) {
    fun isExpired(): Boolean = Instant.now().isAfter(createdAt.plusMillis(ttlMs))
}

data class AuditEvent(
    val operation: String,
    val key: String,
    val nodeId: String,
    val timestamp: Instant,
    val metadata: Map<String, String>?
)

interface AuditSink {
    fun emit(event: AuditEvent)
}

class AsyncAuditSink(private val delegate: AuditSink?) : AuditSink {
    private val buffer = mutableListOf<AuditEvent>()
    private val lock = ReentrantReadWriteLock()

    override fun emit(event: AuditEvent) {
        lock.writeLock().lock()
        try {
            buffer.add(event)
            if (buffer.size >= 10) {
                flush()
            }
        } finally {
            lock.writeLock().unlock()
        }
    }

    fun flush() {
        val snapshot = buffer.toList()
        buffer.clear()
        snapshot.forEach { event ->
            delegate?.emit(event)
        }
    }
}

class NodeRegistry {
    private val nodes = ConcurrentHashMap<String, NodeConnection>()

    fun register(nodeId: String, connection: NodeConnection) {
        nodes[nodeId] = connection
    }

    fun lookup(nodeId: String): NodeConnection? = nodes[nodeId]

    fun resolveOwner(key: String): NodeConnection? {
        if (nodes.isEmpty()) return null
        val hash = key.hashCode().toUInt()
        val nodeList = nodes.entries.sortedBy { it.key }
        val index = (hash % nodeList.size.toUInt()).toInt()
        return nodeList[index].value
    }
}

data class NodeConnection(
    val nodeId: String,
    val host: String,
    val port: Int,
    var healthy: Boolean = true
)

class DistributedCacheClient(
    private val localNodeId: String,
    private val registry: NodeRegistry,
    auditSink: AuditSink? = null
) {
    private val logger = Logger.getLogger(this::class.java.name)
    private val localCache = ConcurrentHashMap<String, CacheEntry>()
    private val audit: AsyncAuditSink = AsyncAuditSink(auditSink)
    private val cacheLock = ReentrantReadWriteLock()

    fun get(key: String): ByteArray? {
        val owner = registry.resolveOwner(key)
        val entry = if (owner?.nodeId == localNodeId) {
            getLocal(key)
        } else {
            getRemote(key, owner)
        }

        val auditMeta = buildAuditMetadata(entry, owner)
        audit.emit(AuditEvent(
            operation = "GET",
            key = key,
            nodeId = owner?.nodeId ?: "unknown",
            timestamp = Instant.now(),
            metadata = auditMeta
        ))

        return entry?.value
    }

    fun put(key: String, value: ByteArray, ttlMs: Long = 60000) {
        val owner = registry.resolveOwner(key)
        val entry = CacheEntry(key, value, ttlMs, Instant.now())

        if (owner?.nodeId == localNodeId) {
            putLocal(entry)
        } else {
            putRemote(entry, owner)
        }

        val auditMeta = buildAuditMetadata(entry, owner)
        audit.emit(AuditEvent(
            operation = "PUT",
            key = key,
            nodeId = owner?.nodeId ?: "unknown",
            timestamp = Instant.now(),
            metadata = auditMeta
        ))
    }

    private fun getLocal(key: String): CacheEntry? {
        cacheLock.readLock().lock()
        try {
            val entry = localCache[key]
            if (entry != null && entry.isExpired()) {
                cacheLock.readLock().unlock()
                cacheLock.writeLock().lock()
                try {
                    localCache.remove(key)
                } finally {
                    cacheLock.writeLock().unlock()
                    cacheLock.readLock().lock()
                }
                return null
            }
            return entry
        } finally {
            cacheLock.readLock().unlock()
        }
    }

    private fun putLocal(entry: CacheEntry) {
        cacheLock.writeLock().lock()
        try {
            localCache[entry.key] = entry
        } finally {
            cacheLock.writeLock().unlock()
        }
    }

    private fun getRemote(key: String, owner: NodeConnection?): CacheEntry? {
        if (owner == null || !owner.healthy) {
            logger.warning("Owner node unavailable for key: $key")
            return null
        }
        // Simulated remote fetch - in production would use gRPC/HTTP
        return null
    }

    private fun putRemote(entry: CacheEntry, owner: NodeConnection?) {
        if (owner == null || !owner.healthy) {
            logger.warning("Owner node unavailable for key: ${entry.key}, storing locally")
            putLocal(entry)
            return
        }
        // Simulated remote put
    }

    private fun buildAuditMetadata(entry: CacheEntry?, owner: NodeConnection?): Map<String, String>? {
        val result = mutableMapOf<String, String>()
        result["localNode"] = localNodeId
        result["ownerNode"] = owner?.nodeId ?: "unresolved"
        result["cacheHit"] = (entry != null).toString()

        // Enrich with entry details when available
        if (entry != null) {
            result["entrySize"] = entry.value.size.toString()
            result["ttl"] = entry.ttlMs.toString()
            result["age"] = java.time.Duration.between(entry.createdAt, Instant.now()).toMillis().toString()
        }

        return if (result.isNotEmpty()) result else null
    }

    fun evict(key: String): Boolean {
        val owner = registry.resolveOwner(key)
        val removed = if (owner?.nodeId == localNodeId) {
            evictLocal(key)
        } else {
            evictRemote(key, owner)
        }

        audit.emit(AuditEvent(
            operation = "EVICT",
            key = key,
            nodeId = owner?.nodeId ?: "unknown",
            timestamp = Instant.now(),
            metadata = mapOf("removed" to removed.toString())
        ))

        return removed
    }

    private fun evictLocal(key: String): Boolean {
        cacheLock.writeLock().lock()
        try {
            return localCache.remove(key) != null
        } finally {
            cacheLock.writeLock().unlock()
        }
    }

    private fun evictRemote(key: String, owner: NodeConnection?): Boolean {
        if (owner == null || !owner.healthy) return false
        return true // simulated
    }

    fun getStats(): CacheStats {
        cacheLock.readLock().lock()
        try {
            val total = localCache.size
            val expired = localCache.values.count { it.isExpired() }
            return CacheStats(total, total - expired, expired)
        } finally {
            cacheLock.readLock().unlock()
        }
    }
}

data class CacheStats(val totalEntries: Int, val activeEntries: Int, val expiredEntries: Int)

// Main entry point demonstrating usage
fun main() {
    val registry = NodeRegistry()
    registry.register("node-1", NodeConnection("node-1", "10.0.0.1", 8080))
    registry.register("node-2", NodeConnection("node-2", "10.0.0.2", 8080))

    // Note: auditSink deliberately left null for lightweight deployments
    val client = DistributedCacheClient("node-1", registry, null)

    client.put("user:123", "Alice".toByteArray())
    val result = client.get("user:123")
    println("Got: ${result?.let { String(it) }}")
    println("Stats: ${client.getStats()}")
}
